/**
 * Generates a log entry for a received user message with the current timestamp, in the format '[<timestamp_iso_format>] Received: <msg>'.
 * Timestamp ISO format is like '2021-09-15T14:30:00'.
 *
 * @param {string} msg - The user message received.
 * @returns {string} The log entry for the received message.
 */
function generate_receive_log(msg) {
  const timestamp = new Date().toISOString();
  // More robust sanitization to prevent log injection attacks.
  // This replaces characters that could be used for injection with their HTML entity equivalents.
  // This approach is generally safer for logs that might be displayed in a web context.
  const sanitizedMsg = msg.replace(/[<>&'"]/g, (match) => {
    switch (match) {
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
      case '&':
        return '&amp;';
      case "'":
        return '&apos;';
      case '"':
        return '&quot;';
      default:
        return match;
    }
  });
  return `[${timestamp}] Received: ${sanitizedMsg}`;
}
